const baseOpenEntry=openEntry;openEntry=function(entry){baseOpenEntry(entry);if(entry?.type==='donation'&&$('#donationKind')){$('#donationKind').value=entry.donationKind||'cash';$('#entryDonationDetail').value=entry.particular||'';updateDonationDetailVisibility()}};
$('#entryForm')?.addEventListener('submit',()=>setTimeout(()=>{const id=$('#entryId').value,entry=state.entries.find(item=>item.id===id);if(entry?.type==='donation'){entry.person=$('#entryPerson').value.trim();entry.particular=$('#entryDonationDetail').value.trim();entry.donationKind=$('#donationKind').value;entry.category=entry.donationKind==='cash'?'Cash Donation':'Item Donation';save();render()}},120));
function applyPrintColors(){const income=state.entries.filter(e=>e.type==='income').reduce((sum,e)=>sum+Number(e.amount||0),0),cash=state.entries.filter(e=>e.type==='donation'&&e.donationKind==='cash').reduce((sum,e)=>sum+Number(e.amount||0),0),expense=state.entries.filter(e=>e.type==='expense').reduce((sum,e)=>sum+Number(e.amount||0),0),balance=income+cash-expense;printReport.querySelector('.print-summary div:nth-child(2)')?.classList.add('expense-total');const final=printReport.querySelector('.print-summary .final');final?.classList.toggle('positive',balance>=0);final?.classList.toggle('negative',balance<0);printReport.querySelectorAll('.print-section h2').forEach(heading=>heading.classList.toggle('green-heading',heading.textContent!=='Expenses'));}
$('#printBtn').onclick=()=>{renderPrintReport();printReport.querySelector('.print-header h1').textContent=`Pal Barir Durga Pujo ${state.activeYear}`;alignPrintTotals();applyPrintColors();window.print();};
openEntry=function(entry){if(!state.hydrated){toast('Please wait while the app finishes loading');return}baseOpenEntry(entry);if(entry?.type==='donation'&&$('#donationKind')){$('#donationKind').value=entry.donationKind||'cash';$('#entryDonationDetail').value=entry.particular||'';updateDonationDetailVisibility()}};
const baseRenderPrintReport=renderPrintReport;renderPrintReport=function(){baseRenderPrintReport();const totalIncome=state.entries.filter(e=>e.type==='income'||e.type==='donation').reduce((sum,e)=>sum+Number(e.amount||0),0),expense=state.entries.filter(e=>e.type==='expense').reduce((sum,e)=>sum+Number(e.amount||0),0),summary=printReport.querySelector('.print-summary');if(summary){summary.querySelector('.final strong').textContent=money(totalIncome-expense)}};applyPrintColors=function(){const income=state.entries.filter(e=>e.type==='income').reduce((sum,e)=>sum+Number(e.amount||0),0),cash=state.entries.filter(e=>e.type==='donation'&&e.donationKind==='cash').reduce((sum,e)=>sum+Number(e.amount||0),0),misc=state.entries.filter(e=>e.type==='donation'&&e.donationKind!=='cash').reduce((sum,e)=>sum+Number(e.amount||0),0),expense=state.entries.filter(e=>e.type==='expense').reduce((sum,e)=>sum+Number(e.amount||0),0),balance=income+cash+misc-expense;printReport.querySelector('.print-summary div:nth-child(2)')?.classList.add('expense-total');const final=printReport.querySelector('.print-summary .final');final?.classList.toggle('positive',balance>=0);final?.classList.toggle('negative',balance<0);printReport.querySelectorAll('.print-section h2').forEach(heading=>heading.classList.toggle('green-heading',heading.textContent!=='Expenses'));};
